import{_ as i,o as n,c as t,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"ATLAS Automation Exporter / Editor","description":"","frontmatter":{},"headers":[],"relativePath":"projects/atlas-plugins/automation-extractor.md","filePath":"projects/atlas-plugins/automation-extractor.md","lastUpdated":1792778683000}'),a={name:"projects/atlas-plugins/automation-extractor.md"};function o(l,e,s,d,u,c){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="atlas-automation-exporter-editor" tabindex="-1">ATLAS Automation Exporter / Editor <a class="header-anchor" href="#atlas-automation-exporter-editor" aria-label="Permalink to &quot;ATLAS Automation Exporter / Editor&quot;">​</a></h1><p>ATLAS Automation Exporter / Editor ist ein eigenständiges, extern gepflegtes ATLAS-Plugin. Die Idee basiert auf dem bisherigen Windows-Werkzeug zum Aufteilen von <code>automations.yaml</code>, wandert aber direkt in die ATLAS-Plugin-Architektur.</p><h2 id="ziel" tabindex="-1">Ziel <a class="header-anchor" href="#ziel" aria-label="Permalink to &quot;Ziel&quot;">​</a></h2><p>Das Plugin analysiert Home-Assistant-Automationen sicher, exportiert ausgewählte Einträge und bereitet die weitere Bearbeitung über File Studio vor.</p><h2 id="repository" tabindex="-1">Repository <a class="header-anchor" href="#repository" aria-label="Permalink to &quot;Repository&quot;">​</a></h2><ul><li>GitHub: <code>https://github.com/rockbaer2007/atlas-automation-exporter-editor-plugin</code></li><li>Installationsseite: <code>https://rockbaer2007.github.io/atlas-automation-exporter-editor-plugin/install.html</code></li><li>Repository-Datei: <code>https://raw.githubusercontent.com/rockbaer2007/atlas-automation-exporter-editor-plugin/main/repository.json</code></li><li>aktueller installierbarer Plugin-Stand: <code>0.1.28</code></li><li>Benutzeroberfläche auf Deutsch, Englisch und Französisch; die gespeicherte ATLAS-Sprache wird beim Öffnen übernommen.</li></ul><p>In ATLAS Administration kann direkt die GitHub-URL eingefügt werden. ATLAS wandelt sie beim Prüfen automatisch in die passende <code>repository.json</code>-Adresse um.</p><p>Seit 0.1.28 zählt die Analyse die tatsächlichen YAML-Einträge von Triggern, Bedingungen und Aktionen. Abschnittsköpfe und verschachtelte Schritte zählen nicht als zusätzliche Haupteinträge. Moderne und klassische Schreibweisen werden unterstützt. Einstellungen und Quellautomationen bleiben unverändert; beim Laden wird vor der Analyse weiterhin eine Sicherheitskopie angelegt.</p><ul><li><code>/config/automations.yaml</code> automatisch über den freigegebenen File-Studio-Pfad lesen</li><li>beim Laden der echten <code>/config/automations.yaml</code> vor der Analyse eine Sicherheitskopie unter <code>/config/atlas_backups/automations/&lt;datum-zeit&gt;/automations.yaml</code> anlegen</li><li>fremde <code>.yaml</code>- und <code>.yml</code>-Dateien per Upload analysieren</li><li>ID, Alias, Beschreibung, Trigger, Conditions und Actions anzeigen</li><li>Service-Aufrufe aus klassischem <code>service:</code> und modernem <code>action: domain.service</code> erkennen</li><li>einzelne Automationen mit Trigger- oder Action-Fragmenten auf Root-Ebene als einen Eintrag behalten, statt daraus falsche Mehrfachkonflikte zu erzeugen</li><li>Zeittrigger beim Export als quoted <code>HH:MM:SS</code> erhalten und numerische Sekundenwerte wie <code>25200</code> wieder als <code>&#39;07:00:00&#39;</code> ausgeben</li><li>Analysehinweise für fehlende oder doppelte IDs/Aliasse, fehlende Trigger oder Actions und deaktivierte Automationen anzeigen</li><li>doppelte IDs und Aliasse direkt in der Automationsliste als Konflikte vormarkieren</li><li>doppelte IDs und Aliasse als Konflikte getrennt von allgemeinen Hinweisen anzeigen</li><li>nur Automationen mit Hinweisen filtern</li><li>Detail-YAML farbig wie im File Studio darstellen</li><li>Automationsliste auf ungefähr 15 sichtbare Einträge begrenzen und intern scrollbar halten</li><li>beteiligte Entitäten, Scripts, Szenen, Helfer und Benachrichtigungsziele sichtbar machen</li><li>Automationsliste nach Domain, Bereich oder Gerät gruppieren und filtern</li><li>Export-Ordner als Zielvorgabe festlegen</li><li>ausgewählte Automationen in einen Laufordner mit Datum und Uhrzeit exportieren</li><li>pro Automation zwei Dateien mit gleichem Namen erzeugen: <code>export-version</code> mit <code>id</code> und <code>bereinigte-import-version</code> ohne <code>id</code> für den Home-Assistant-YAML-Editor</li><li>exportierte Automationen in einer Übersicht anzeigen</li><li>Bearbeitung der exportierten Dateien über File Studio vorbereiten</li></ul><h2 id="sicherheitslinie" tabindex="-1">Sicherheitslinie <a class="header-anchor" href="#sicherheitslinie" aria-label="Permalink to &quot;Sicherheitslinie&quot;">​</a></h2><p>Das Plugin schreibt nicht in Home-Assistant-Systemdateien zurück. Es liest System-YAML oder hochgeladene YAML-Dateien, legt beim Öffnen der echten <code>automations.yaml</code> eine Sicherheitskopie an, analysiert die Automationen und exportiert getrennte YAML-Dateien. Manuelle Wiederherstellung und spätere Bearbeitung laufen über File Studio und die Home-Assistant-YAML-Werkzeuge.</p><h2 id="sichere-plugin-wiederherstellung" tabindex="-1">Sichere Plugin-Wiederherstellung <a class="header-anchor" href="#sichere-plugin-wiederherstellung" aria-label="Permalink to &quot;Sichere Plugin-Wiederherstellung&quot;">​</a></h2><p>In <strong>Administration → Plugin-Manager → Automation Exporter / Editor → Wiederherstellen</strong> eine vorhandene Sicherung auswählen. Version, Richtung und Kompatibilität in der Vorschau prüfen und erst dann <strong>Sichern und übernehmen</strong> ausführen. ATLAS sichert dabei auch die aktuell installierte Plugin-Version. <strong>Abbrechen</strong> lässt die Installation unverändert. Nach einer zwischenzeitlichen Änderung am Plugin-/Verwaltungsstand muss eine neue Vorschau erstellt werden.</p><p>Damit wird das <strong>Plugin-Paket</strong> wiederhergestellt. Quellautomationen, exportierte Dateien, Editor-Projekte sowie Papierkorb und Historie werden dadurch nicht auf einen früheren Datenstand zurückgesetzt. Es gibt keinen automatischen Import nach Home Assistant und kein Zurückschreiben in <code>automations.yaml</code>.</p><div class="info custom-block"><p class="custom-block-title">Isoliert geprüft am 16.10.2026</p><p>Mit ATLAS 0.1.312 wurden echte Pakete <strong>0.1.27 → 0.1.28 → 0.1.27 → 0.1.28</strong> geprüft, einschließlich Neustart, UI-Vorschau, Abbruch und Übernahme. Eine veraltete Vorschau wurde nach einer echten Verwaltungsänderung zurückgewiesen. Vorher wurden Repositories und die vollständigen isolierten Testdaten gesichert. Quell-YAML, vorhandene Exporte, Projekt, anderes Plugin, Papierkorb und Historie blieben beim Dateivergleich erhalten. Analyse in DE/EN/FR, bytegleiche Sicherheitskopien, Exportpaare mit/ohne ID und Öffnen im File Studio bestanden. Die HA-Version kam von einem lokalen Testendpunkt; das ist kein Test einer echten HA-Verbindung, eines GitHub-Updates oder einer Datenformat-Migration. <strong>Pi 5 und Proxmox wurden bei dieser isolierten Prüfung nicht verändert.</strong></p></div><div class="info custom-block"><p class="custom-block-title">Anschließend auf Pi 5 und Proxmox geprüft am 16.10.2026</p><p>Nach neuen lokalen HA-Backups und zusätzlichen PC-Sicherungen wurde auf beiden Hosts <strong>die installierte 0.1.28 → 0.1.27 → ursprüngliche 0.1.28</strong> geprüft. Der Wechsel auf das echte ältere Paket nutzte die Kompatibilitätsvorschau des Backends; Abbruch und Wiederherstellung der neu erzeugten Sicherung liefen über die Administration. Beide Hosts behalten ATLAS 0.1.312 und HA 2026.10.1.</p><p>Alle neun ursprünglichen Plugin-Dateien wurden exakt wiederhergestellt. Geprüfte Quellautomationen, vorhandene Exporte und Automations-Backups, Einstellungen, Server-Projekte, andere Plugins, Papierkorb und Historie blieben erhalten. Die Analyse einer eigenen hochgeladenen Test-YAML war vor und nach der Wiederherstellung identisch. Dafür wurden keine Nutzerautomationen exportiert, ausgeführt oder in HA zurückgeschrieben; ein HA-/App-Neustart war nicht nötig. Die nativen Prüfungen ersetzen keinen vollständigen HA-Restoretest und prüfen keine Datenformat-Migration oder neue GitHub-Veröffentlichung.</p></div><p>Nach der Wiederherstellung Administration und Plugin-Seite neu laden. Im Test zeigte die noch offene Administration kurz „Änderungen noch nicht gemeinsam gespeichert“, obwohl der Serverstand korrekt wiederhergestellt war. Nach dem Neuladen wurde wieder der gemeinsame Serverstand angezeigt. Nicht allein wegen dieser Meldung einen alten lokalen Stand übernehmen.</p><p>Sprache und Darstellung werden lokal gespeichert. Geladene Analyse, Auswahl, Filter, eingegebener Export-Ordner und Exportübersicht gehören zur aktuellen Sitzung. Nach Neuladen die Quelle erneut laden und den Zielordner bei Bedarf erneut wählen. Bereits gespeicherte Exportdateien bleiben erhalten und können im File Studio geöffnet werden.</p><h2 id="einordnung" tabindex="-1">Einordnung <a class="header-anchor" href="#einordnung" aria-label="Permalink to &quot;Einordnung&quot;">​</a></h2><p>ATLAS Automation Exporter / Editor ergänzt File Studio: File Studio ist die sichere Dateioberfläche, der Automation Exporter / Editor ist die fachliche Analyse- und Exportoberfläche für Automationen.</p>',20)])])}const m=i(a,[["render",o]]);export{g as __pageData,m as default};
